@startuml

class Driver {
  + ID : int
  + Name : string
  + IsOnSickLeave : boolean
}

class Bus {
  + LicensePlate : string
  + IsInRepairShop : boolean
}

class Route {
  + RouteNumber : int
}

class Shift {
  + ShiftType : ShiftType
}

class Schedule {
  + Date : date
}

enum ShiftType {
  Morning
  Afternoon
  Night
}

class CityStaff {}

CityStaff "1" -- "*" Driver : manages
CityStaff "1" -- "*" Bus : manages
CityStaff "1" -- "*" Route : manages
CityStaff "1" -- "*" Schedule : manages

Route "1" -- "*" Schedule
Schedule "1" -- "*" Shift
Bus "1" -- "*" Shift
Driver "1" -- "*" Shift

@enduml

